// src/db/connection.ts

interface QueryResult {
  [key: string]: unknown;
}

interface DatabaseConnection {
  query(sql: string, params?: unknown[]): Promise<QueryResult[]>;
}

// In-memory database implementation
class InMemoryDatabase implements DatabaseConnection {
  private tables: Map<string, Map<string, QueryResult>> = new Map();
  private sequences: Map<string, number> = new Map();

  constructor() {
    this.initializeTables();
  }

  private initializeTables(): void {
    this.tables.set('departments', new Map());
    this.tables.set('users', new Map());
    this.tables.set('unreported_members', new Map());
    this.tables.set('mail_queue', new Map());
    this.tables.set('audit_log', new Map());
  }

  async query(sql: string, params: unknown[] = []): Promise<QueryResult[]> {
    const trimmedSql = sql.trim();

    // DELETE queries
    if (trimmedSql.toUpperCase().startsWith('DELETE')) {
      return this.handleDelete(trimmedSql, params);
    }

    // INSERT queries
    if (trimmedSql.toUpperCase().startsWith('INSERT')) {
      return this.handleInsert(trimmedSql, params);
    }

    // SELECT queries
    if (trimmedSql.toUpperCase().startsWith('SELECT')) {
      return this.handleSelect(trimmedSql, params);
    }

    return [];
  }

  private handleDelete(sql: string, params: unknown[]): Promise<QueryResult[]> {
    const tableMatch = sql.match(/DELETE\s+FROM\s+(\w+)/i);
    if (!tableMatch) return Promise.resolve([]);

    const tableName = tableMatch[1];
    const table = this.tables.get(tableName);
    if (!table) return Promise.resolve([]);

    const whereMatch = sql.match(/WHERE\s+(.+?)(?:$|;)/i);
    if (!whereMatch) {
      table.clear();
      return Promise.resolve([]);
    }

    const whereClause = whereMatch[1];
    const keysToDelete: string[] = [];

    table.forEach((row, key) => {
      if (this.evaluateWhere(whereClause, row, params)) {
        keysToDelete.push(key);
      }
    });

    keysToDelete.forEach((key) => table.delete(key));
    return Promise.resolve([]);
  }

  private handleInsert(sql: string, params: unknown[]): Promise<QueryResult[]> {
    const tableMatch = sql.match(/INSERT\s+INTO\s+(\w+)/i);
    if (!tableMatch) return Promise.resolve([]);

    const tableName = tableMatch[1];
    const table = this.tables.get(tableName);
    if (!table) return Promise.resolve([]);

    const columnsMatch = sql.match(/\(([^)]+)\)/);
    if (!columnsMatch) return Promise.resolve([]);

    const columns = columnsMatch[1].split(',').map((c) => c.trim());
    const row: QueryResult = {};
    let paramIndex = 0;

    for (const col of columns) {
      if (col === 'created_at' && sql.toUpperCase().includes('NOW()')) {
        row[col] = new Date().toISOString();
      } else if (paramIndex < params.length) {
        row[col] = params[paramIndex];
        paramIndex++;
      }
    }

    const keyCol = this.getPrimaryKeyColumn(tableName);
    const key = String(row[keyCol] || this.generateId(tableName));
    row[keyCol] = key;

    table.set(key, row);

    const returningMatch = sql.match(/RETURNING\s+(\w+)/i);
    if (returningMatch) {
      const returningCol = returningMatch[1];
      return Promise.resolve([{ [returningCol]: row[returningCol] }]);
    }

    return Promise.resolve([]);
  }

  private handleSelect(sql: string, params: unknown[]): Promise<QueryResult[]> {
    const tableMatch = sql.match(/FROM\s+(\w+)/i);
    if (!tableMatch) return Promise.resolve([]);

    const tableName = tableMatch[1];
    const table = this.tables.get(tableName);
    if (!table) return Promise.resolve([]);

    let results: QueryResult[] = Array.from(table.values());

    const whereMatch = sql.match(/WHERE\s+(.+?)(?:$|;)/i);
    if (whereMatch) {
      const whereClause = whereMatch[1];
      results = results.filter((row) =>
        this.evaluateWhere(whereClause, row, params)
      );
    }

    const selectMatch = sql.match(/SELECT\s+(.+?)\s+FROM/i);
    if (selectMatch) {
      const selectClause = selectMatch[1];
      if (selectClause.includes('COUNT(*)')) {
        return Promise.resolve([{ cnt: results.length }]);
      }
    }

    return Promise.resolve(results);
  }

  private evaluateWhere(
    whereClause: string,
    row: QueryResult,
    params: unknown[]
  ): boolean {
    if (whereClause.includes('=')) {
      const parts = whereClause.split('=').map((p) => p.trim());
      const colName = parts[0];
      if (parts[1] === '?') {
        return row[colName] === params[0];
      }
    }
    return true;
  }

  private getPrimaryKeyColumn(tableName: string): string {
    const keyMap: Record<string, string> = {
      departments: 'department_id',
      users: 'user_id',
      unreported_members: 'list_id',
      mail_queue: 'id',
      audit_log: 'id',
    };
    return keyMap[tableName] || 'id';
  }

  private generateId(tableName: string): string {
    const current = this.sequences.get(tableName) || 0;
    const next = current + 1;
    this.sequences.set(tableName, next);
    return `${tableName}_${next}`;
  }
}

let connectionInstance: DatabaseConnection | null = null;

export function getConnection(): DatabaseConnection {
  if (!connectionInstance) {
    connectionInstance = new InMemoryDatabase();
  }
  return connectionInstance;
}
